25	bool SeqFile::read_line(std::string& out) {
26	    out.clear();
27	    int c;
28	    bool any = false;
29	    while ((c = getc()) >= 0) {
30	        any = true;
31	        if (c == '\n') break;
32	        out.push_back((char)c);
33	    }
34	    if (!any && out.empty()) return false;
35	    if (!out.empty() && out.back() == '\r') out.pop_back();
36	    return true;
37	}
38	
39	int SeqFile::next(SeqRecord& r) {
40	    r.clear();
41	    int c = getc();
42	    if (c < 0) return 0;
43	    if (c != '>' && c != '@') return -2;
44	    // header line
45	    std::string line;
46	    read_line(line);
47	    size_t i = 0;
48	    while (i < line.size() && !isspace((unsigned char)line[i])) ++i;
49	    r.name = line.substr(0, i);
50	    if (i < line.size()) r.comment = line.substr(i + 1);
51	    // sequence lines
52	    for (;;) {
53	        c = getc();
54	        if (c < 0) { r.is_fastq = false; return 1; }
55	        if (c == '+') { // quality follows
56	            r.is_fastq = true;
57	            read_line(line); // discard '+' line content
58	            while (r.qual.size() < r.seq.size()) {
59	                if (!read_line(line)) break;
60	                r.qual += line;
61	            }
62	            return 1;
63	        }
64	        if (c == '>' || c == '@') { ungetc(c); r.is_fastq = false; return 1; }
65	        ungetc(c);
66	        if (!read_line(line)) { return 1; }
67	        r.seq += line;
68	    }
69	}
